import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const _=JSON.parse('{"title":"第九章 エンド帝国","description":"","frontmatter":{},"headers":[],"relativePath":"story/2-3.md","filePath":"story/2-3.md"}'),o={name:"story/2-3.md"};function h(i,p,l,n,s,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="第九章-エンド帝国" tabindex="-1">第九章 エンド帝国 <a class="header-anchor" href="#第九章-エンド帝国" aria-label="Permalink to &quot;第九章 エンド帝国&quot;">​</a></h1><p>王国歴十二年。</p><p>北方防衛戦から、数週間。</p><p>王国軍は、一時的な勝利を収めていた。</p><p>しかし、その勝利は、誰の顔にも安堵をもたらさなかった。</p><p>「陛下。」</p><p>「偵察隊より報告です。」</p><p>王立情報局長官が、震える声で言った。羊皮紙を持つ手が、小さく震えていた。</p><p>「敵の転移門。」</p><p>「一つではありません。」</p><p>「全部で……。」</p><p>「三百。」</p><p>会議室が、静まり返った。</p><p>三百という数字が、言葉として理解されるまでに、数秒の時間がかかった。</p><p>元帥が、青ざめた。椅子に手をつき、体を支えた。</p><p>「三百だと……。」</p><p>ピックバーグは、古文書を広げた。指先が、紙の上を滑る。</p><p>「やはり。」</p><p>「エンド帝国だ。」</p><p>「しかも。」</p><p>「第四軍団だけじゃない。」</p><p>「第一軍団。」</p><p>「第二軍団。」</p><p>「第三軍団。」</p><p>「第五軍団。」</p><p>「そして。」</p><p>「皇帝親衛軍。」</p><p>一つ一つの名前が、まるで石を積むように、重く、会議室にのしかかった。</p><p>スターリンが、顔をしかめた。</p><p>「つまり。」</p><p>「もっと化け物がいるってことか。」</p><p>「そう。」</p><p>「しかも。」</p><p>「ENDER LORDより強い。」</p><p>その言葉に、会議室の空気が、一段と冷えた。</p><hr><h1 id="第十章-皇帝親衛軍" tabindex="-1">第十章 皇帝親衛軍 <a class="header-anchor" href="#第十章-皇帝親衛軍" aria-label="Permalink to &quot;第十章 皇帝親衛軍&quot;">​</a></h1><p>数日後。</p><p>南方要塞。</p><p>空が、紫色に染まった。</p><p>「敵襲！！」</p><p>警報が、鳴り響いた。</p><p>兵士たちは、武器を構えた。これまでの戦いで、彼らも経験を積んでいた。多少の敵なら、退けられる自信があった。</p><p>しかし。</p><p>そこにいた兵士たちは、すぐに、絶望することになる。</p><p>空間から現れたのは、たった百人。</p><p>「たった百人？」</p><p>兵士たちは、思わず笑った。三百の転移門という報告を聞いていたからこそ、百人という数は、拍子抜けするほど少なく感じられた。</p><p>次の瞬間。</p><p>ドォォォォン！！</p><p>要塞の壁が、吹き飛んだ。</p><p>石材が、まるで紙のように、空へ舞った。</p><p>「なっ！？」</p><p>「うそだろ！？」</p><p>百人の黒い戦士。</p><p>漆黒の鎧が、紫色の炎を纏っていた。</p><p>その旗には、黒曜石の王冠が描かれていた。</p><p>「皇帝親衛軍……。」</p><p>報告を聞いたピックバーグが、震えた。</p><p>「エンド帝国最強。」</p><p>「一人で、千人に匹敵する。」</p><p>その中央に、一人の騎士が立っていた。</p><p>漆黒の鎧の中で、紫色の瞳だけが、冷たく光っていた。</p><p>「我が名は。」</p><p>「NIGHTMARE。」</p><p>「皇帝親衛隊長。」</p><p>「黄金王。」</p><p>「皇帝陛下がお呼びだ。」</p><p>その声には、命令ではなく、確信があった。</p><p>来るに決まっている、という確信。</p><p>抗うことなど、最初から想定されていない、という確信。</p><hr><h1 id="第十一章-エンダーワールド" tabindex="-1">第十一章 エンダーワールド <a class="header-anchor" href="#第十一章-エンダーワールド" aria-label="Permalink to &quot;第十一章 エンダーワールド&quot;">​</a></h1><p>巨大な転移門。</p><p>その向こうに、足を踏み入れた瞬間、三人は言葉を失った。</p><p>誰も見たことのない世界が、そこに広がっていた。</p><p>空に浮かぶ、無数の島々。重力を無視したように、ただ静かに浮遊していた。</p><p>紫色の海。波というより、光の膜が、ゆっくりと揺れているようだった。</p><p>黒曜石の都市。鋭く尖った建物が、まるで結晶のように、空へ向かって伸びていた。</p><p>そして。</p><p>無数のエンダーマンが、街路を行き来していた。普段の侵略者としての姿ではなく、ただの住人として。小さなエンダーマンの子供が、親の後ろを歩いていた。</p><p>「これが……。」</p><p>「エンド帝国。」</p><p>スターリンも、息を呑んだ。</p><p>「でかすぎる。」</p><p>ピックバーグは、青ざめていた。それでも、研究者としての目は、止まらなかった。</p><p>「記録以上だ。」</p><p>「滅んでなんかいなかった。」</p><p>「眠っていただけなんだ。」</p><p>天を貫く、巨大な宮殿が、彼らを見下ろしていた。</p><p>宮殿の奥。</p><p>玉座。</p><p>そこに座る者の姿が、ゆっくりと、見えてきた。</p><p>黄金王よりも、なお大きな身体。</p><p>漆黒の王冠。</p><p>紫色の、深く澄んだ目。</p><p>静寂が、玉座の間を満たしていた。</p><p>そして。</p><p>その者は、ゆっくりと、立ち上がった。</p><p>「久しいな。」</p><p>「地上の王よ。」</p><p>「……。」</p><p>オーレックスは、何も言えなかった。</p><p>「私は。」</p><p>「ENDER EMPEROR。」</p><p>「エンド帝国皇帝。」</p><p>その威圧感に、数々の死線をくぐってきたスターリンですら、汗を流した。</p><hr><h1 id="第十二章-皇帝" tabindex="-1">第十二章 皇帝 <a class="header-anchor" href="#第十二章-皇帝" aria-label="Permalink to &quot;第十二章 皇帝&quot;">​</a></h1><p>「なぜ戦う！」</p><p>オーレックスは、声を張った。</p><p>「なぜ侵略する！」</p><p>皇帝は、静かに答えた。声には、怒りも、敵意もなかった。あるのは、ただ、深い疲労だけだった。</p><p>「生きるためだ。」</p><p>「我らの世界は、滅びかけている。」</p><p>「資源は尽き。」</p><p>「民は減り。」</p><p>「このままでは、終わる。」</p><p>「だから。」</p><p>「新たな世界を、手に入れる。」</p><p>「力で。」</p><p>オーレックスは、首を振った。</p><p>「違う！」</p><p>「奪うことが、答えじゃない！」</p><p>「共に生きる道がある！」</p><p>それは、彼がネザーを旅して、繰り返し確かめてきた言葉だった。村を救い、橋を架け、誰かを助けるたびに、確かめてきた言葉だった。</p><p>しかし。</p><p>皇帝は、悲しそうに笑った。それは、嘲りではなかった。むしろ、懐かしむような笑みだった。</p><p>「かつて。」</p><p>「私もそう信じていた。」</p><p>「だが。」</p><p>「数千年。」</p><p>「答えは、得られなかった。」</p><p>数千年という言葉の重さを、オーレックスは、想像することしかできなかった。たかだか数十年しか生きていない自分には、その絶望の深さを、本当には測れない。</p><p>「ならば。」</p><p>「力しかない。」</p><p>皇帝は、ゆっくりと、剣を抜いた。</p><p>黒曜石の刃が、紫色の光を反射した。</p><p>「黄金王。」</p><p>「お前を倒し。」</p><p>「世界を統一する。」</p><p>その言葉に、迷いはなかった。少なくとも、表面上は。</p><p>しかし。</p><p>オーレックスは、ふと、何かに気づいた。</p><p>皇帝の目の奥に、わずかに揺れる光があった。</p><p>確信ではなく、迷いに似た、何か。</p><p>それが何なのか、確かめる時間は、与えられなかった。</p><hr><h1 id="第十三章-黄金王対皇帝" tabindex="-1">第十三章 黄金王対皇帝 <a class="header-anchor" href="#第十三章-黄金王対皇帝" aria-label="Permalink to &quot;第十三章 黄金王対皇帝&quot;">​</a></h1><p>ガァァァン！！</p><p>黄金の剣と、黒曜石の剣がぶつかり、世界そのものが、揺れた気がした。</p><p>衝撃波が、玉座の間の柱を軋ませた。</p><p>紫色の雷が、空間を裂いた。</p><p>「うおおお！」</p><p>スターリンは、親衛隊長NIGHTMAREと激突していた。大斧と黒曜石の剣が、何度も交差する。一撃ごとに、火花が散った。</p><p>「お前、強えな！」</p><p>「皇帝陛下の剣を学んだ者だ。」</p><p>「光栄に思うがいい。」</p><p>「それより名前覚えにくい！」</p><p>戦いの最中だというのに、スターリンの口は止まらなかった。それが、彼の戦い方だった。恐怖を、笑いに変える戦い方。</p><p>一方。</p><p>ピックバーグは、戦いから離れ、宮殿の地下へ向かっていた。古文書に記された、ある一文が、頭から離れなかった。</p><p>『黄金とは、富ではない。希望そのものである。』</p><p>忘れられた砦で聞いた言葉が、なぜか今、頭の中で鳴っていた。</p><p>地下に降りると、巨大な黒曜石の機械が見えた。</p><p>「そうか！」</p><p>「これだ！」</p><p>「原因は、これなんだ！」</p><p>機械の中心に、巨大な、ひび割れた卵があった。</p><p>近づくにつれ、空気が、重くなっていくのを感じた。</p><p>「まさか……。」</p><p>「そんな。」</p><p>ピックバーグは、絶望に近い顔で、その卵を見上げた。</p><p>「エンダードラゴン。」</p><p>「まだ生きていたのか……。」</p><p>その時。</p><p>卵の奥から、声が響いた。</p><p>声というより、頭の中に直接、染み込んでくる何かだった。</p><p>『我を解放せよ。』</p><p>『全てを滅ぼそう。』</p><p>ピックバーグの顔色が、変わった。</p><p>何かが、繋がった気がした。</p><p>彼は、転移装置の脇に置かれた書物に、目を走らせた。古い、誰にも読まれていない記録。皇帝が、何のために兵を動かしていたのか――その本当の意味が、そこに記されていた。</p><p>「違う。」</p><p>「皇帝は、侵略者じゃない！」</p><p>「操られてる！」</p><p>その叫びが、地下から、玉座の間まで響いた。</p><hr><h1 id="第十四章-真の敵" tabindex="-1">第十四章 真の敵 <a class="header-anchor" href="#第十四章-真の敵" aria-label="Permalink to &quot;第十四章 真の敵&quot;">​</a></h1><p>「オーレックス！」</p><p>ピックバーグが、階段を駆け上がりながら叫んだ。</p><p>「戦っちゃ駄目だ！」</p><p>「皇帝は、操られてる！」</p><p>「何！？」</p><p>剣を構えたまま、オーレックスが振り返った。</p><p>その瞬間。</p><p>巨大な声が、宮殿全体を揺らした。</p><p>『愚かな者たちよ。』</p><p>『我は終焉。』</p><p>『我は破滅。』</p><p>『我は竜王。』</p><p>ゴォォォォォ！！</p><p>地下から、卵が砕ける音が響いた。</p><p>そして。</p><p>天井を突き破り、巨大な翼を持つ影が、玉座の間に現れた。</p><p>紫色の瞳。何もかもを見下すような、巨大な瞳。</p><p>「エンダードラゴン！」</p><p>スターリンも、絶句した。</p><p>皇帝も、目を見開いた。</p><p>「まさか……。」</p><p>「封印が……。」</p><p>数千年間。</p><p>エンド帝国は、戦っていた。</p><p>世界を支配するためではなく。</p><p>このドラゴンを、封じ込めるために。</p><p>その事実が、ようやく、すべての辻褄を合わせた。資源の枯渇。民の減少。終わらない遠征。それらは全て、封印を維持するための、数千年にわたる消耗戦の結果だったのだ。</p><p>皇帝は、剣を取り落とした。</p><p>そして、膝をついた。</p><p>「すまなかった。」</p><p>「黄金王。」</p><p>その声には、もう、威圧も、敵意もなかった。あったのは、数千年分の疲労と、そして、わずかな安堵だった。誤解が解けたことへの、安堵だった。</p><p>オーレックスは、剣を下げた。</p><p>そして、微笑んだ。</p><p>「一緒に戦おう。」</p><p>皇帝も、笑った。</p><p>数千年ぶりに。</p><p>「……ああ。」</p><p>その一言には、数千年分の孤独が、溶けていくような響きがあった。</p><hr><h1 id="終章" tabindex="-1">終章 <a class="header-anchor" href="#終章" aria-label="Permalink to &quot;終章&quot;">​</a></h1><p>こうして。</p><p>黄金王。</p><p>スターリン。</p><p>ピックバーグ。</p><p>そして。</p><p>エンド帝国皇帝。</p><p>四人は、真の敵――エンダードラゴンとの戦いへ、向かう。</p><p>力で支配しようとした帝国も、平和を願って旅をした王も、最後に立ち向かう敵は、同じだった。</p><p>黄金とは、富ではない。</p><p>希望そのものである。</p><p>忘れられた砦で聞いた言葉が、今、確かな意味を持って、オーレックスの中に在った。</p><p>後に。</p><p>この戦いは。</p><p>「黒曜石戦争」</p><p>と呼ばれることになる。</p><p>そして。</p><p>誰も知らない。</p><p>さらに恐ろしい存在。</p><p>古代エンダードラゴン。</p><p>そして。</p><p>世界を創った者たち。</p><p>ANCIENTS。</p><p>彼らとの戦いが、まだ、始まってすらいないことを。</p><p>新たな歯車が、静かに、回り始めていた。</p><hr><p>PIGLIN KING</p><p>第二巻 黒曜石戦争</p><p>完</p>',258)])])}const u=a(o,[["render",h]]);export{_ as __pageData,u as default};
